  const w = normalized;

  if(!endsWithSos(w)){
    return {ok:false, msg:"This toy expects a disyllabic-looking word ending in -σος."};
  }

  const groups = lastIndexOfGreekVowelGroup(w);
  const syllables = groups.length;
  const pen = groups[groups.length-2];
  const penText = pen ? pen.text.toLowerCase() : '';

  // Determine penult category
  const penCat = (()=>{
    if(!pen) return 'unknown';
    if(pen.type==='diph') return 'diphthong';
    if(penText==='η') return 'eta';
    if(penText==='ω') return 'omega';
    if(penText==='ι' || penText==='υ') return 'i/u';
    return 'other';
  })();

  // Heuristic accent decision
  let decision = 'barytone';
  let why = [];
  let badge = 'good';
  let notes = [];

  if(syllables!==2){
    badge='warn';
    notes.push(`Detected ${syllables} vowel-groups (toy is tuned for disyllables).`);
  }

  if(penCat==='eta'){
    decision='barytone';
    why.push("Penult has η → barytone (Herodian’s rule for -ησος disyllables)." );
    notes.push("Exception mentioned: νῆσος is feminine though most others are masculine (gender not handled)." );
  } else if(penCat==='omega'){
    // passage: feminine -ωσος oxytone; but exceptions Σῶσος, Κρῶσος (masc) barytone
    decision='oxytone';
    why.push("Penult has ω → often oxytone for feminine -ωσος (per passage)." );
    notes.push("But Σῶσος (from σώσω) and Κρῶσος (masc.) are barytone exceptions." );
    badge='warn';
  } else if(penCat==='i/u'){
    decision='barytone';
    why.push("Penult has long ι/υ (often written with circumflex in examples) → barytone for many proper names/monogender nouns." );
    badge='good';
  } else if(penCat==='diphthong'){
    if(opts.cityAdj){
      decision='oxytone';
      why.push("Penult has diphthong and you marked “city/adjective” → oxytone (Παισός-type rule)." );
      badge='good';
    } else {
      decision='oxytone';
      why.push("Penult has diphthong → often oxytone for adjectives/place-names (mark the checkbox if that’s intended)." );
      badge='warn';
    }
  } else {
    decision='barytone';
    why.push("No special penult pattern detected → defaulting to barytone (toy default)." );
    badge='warn';
  }

  // Produce a playful re-accenting
  const reaccented = (decision==='oxytone') ? applyAcuteToLastVowel(w) : applyAcuteToPenultVowel(w);

  return {
    ok:true,
    original,
    used:w,
    syllables,
    penult: pen ? pen.text : '—',
    penCat,
    decision,
    reaccented,
    why,
    notes,
    badge
  };
}

function render(res){
  const out = $('#out');
  if(!res.ok){
    out.innerHTML = `<div class="kv"><div class="k">Message</div><div class="v">${escapeHtml(res.msg)}</div></div>`;
    return;
  }
  const badgeClass = res.badge;
  const badgeText = badgeClass==='good'?'confident-ish':(badgeClass==='warn'?'heuristic':'');

  out.innerHTML = `
    <div class="kv">
      <div class="k">Input</div>
      <div class="v mono">${escapeHtml(res.original)}</div>

      <div class="k">Analyzed as</div>
      <div class="v mono">${escapeHtml(res.used)}</div>

      <div class="k">Penult vowel-group</div>
      <div class="v mono">${escapeHtml(res.penult)} <span class="badge ${badgeClass}">${badgeText}</span></div>

      <div class="k">Toy verdict</div>
      <div class="v"><b>${escapeHtml(res.decision)}</b> (barytone = not final; oxytone = final)</div>

      <div class="k">Toy re-accenting</div>
      <div class="v mono">${escapeHtml(res.reaccented)}</div>

      <div class="k">Reason</div>
      <div class="v">${res.why.map(x=>`<div>• ${escapeHtml(x)}</div>`).join('')}</div>

      <div class="k">Notes</div>
      <div class="v">${(res.notes.length?res.notes.map(x=>`<div>• ${escapeHtml(x)}</div>`).join(''):'—')}</div>
    </div>
  `;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[c]));
}

