// --- Mini game ---
let current = null;
let selected = null;

const CHOICES = [
  {id:'eta', label:'η (…ησος)'},
  {id:'omega', label:'ω (…ωσος)'},
  {id:'i/u', label:'ι/υ (…ισος/…υσος)'},
  {id:'diphthong', label:'diphthong (αι/ει/οι/…)'},
  {id:'other', label:'other'}
];

function setupChoices(){
  const box = $('#choices');
  box.innerHTML='';
  CHOICES.forEach(c=>{
    const d=document.createElement('div');
    d.className='choice';
    d.textContent=c.label;
    d.dataset.id=c.id;
    d.addEventListener('click', ()=>{
      selected=c.id;
      Array.from(box.children).forEach(x=>x.classList.toggle('sel', x.dataset.id===selected));
      $('#gameMsg').textContent='';
    });
    box.appendChild(d);
  });
}

function newRound(){
  current = pickExample();
  selected = null;
  $('#gameWord').textContent = current.w;
  Array.from($('#choices').children).forEach(x=>x.classList.remove('sel'));
  $('#gameMsg').textContent = 'Pick the penult category, then Reveal.';
}

$('#reveal').addEventListener('click', ()=>{
  if(!current) return;
  const res = classify(current.w, {strip:true, cityAdj: current.cityAdj});
  const correct = res.penCat;
  const msg = [];
  msg.push(`Penult vowel-group: ${res.penult} → category: ${correct}.`);
  msg.push(`Toy verdict: ${res.decision}.`);
  if(selected){
    msg.push(selected===correct ? 'Your pick: correct.' : `Your pick: ${selected} (not this time).`);
  } else {
    msg.push('You did not pick a category.' );
  }
  $('#gameMsg').textContent = msg.join(' ');
});

$('#newRound').addEventListener('click', newRound);

setupChoices();
newRound();

